def record_existing_payments(apps, schema_editor):
    """Bills marked paid before payment records existed get one confirmed payment for their
    full amount (method "other"), numbered in the order they were paid, so every paid bill
    has a payment and a receipt."""
    from decimal import Decimal
    from django.db.models import Sum
    from django.utils import timezone
    Bill = apps.get_model("residency", "Bill")
    BillItem = apps.get_model("residency", "BillItem")
    Building = apps.get_model("residency", "Building")
    Payment = apps.get_model("residency", "Payment")

    for building in Building.objects.all():
        letters = "".join(w[0] for w in building.name.split() if w[:1].isalpha()).upper()
        code = (letters or "GR")[:3]
        counter = building.receipt_counter
        paid = Bill.objects.filter(unit__floor__building=building, status="paid").order_by("paid_at", "id")
        for bill in paid:
            total = BillItem.objects.filter(bill=bill).aggregate(t=Sum("amount"))["t"] or Decimal(0)
            if total <= 0:
                continue
            when = bill.paid_at or timezone.now()
            counter += 1
            Payment.objects.create(
                bill=bill, amount=total, kind="other", paid_on=timezone.localtime(when).date(),
                note="Recorded before payment details were tracked", status="confirmed",
                submitted_by=bill.created_by, decided_by=bill.created_by, decided_at=when,
                receipt_no=f"{code}-{when:%Y}-{counter:04d}",
            )
        building.receipt_counter = counter
        building.save(update_fields=["receipt_counter"])


